package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="api_endpoints")
public class ApiEndpoint { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(name="entity_id",nullable=false) private UUID entityId; @Column(nullable=false,length=255) private String path; @Column(name="http_method",nullable=false,length=20) private String httpMethod; @Column(name="operation_name",nullable=false,length=100) private String operationName; @Column(name="request_dto",length=100) private String requestDto; @Column(name="response_dto",length=100) private String responseDto; @Column(name="requires_auth",nullable=false) private boolean requiresAuth=true; @Column(columnDefinition="text") private String description;
 public UUID getId(){return id;} public UUID getProjectId(){return projectId;} public void setProjectId(UUID v){projectId=v;} public UUID getEntityId(){return entityId;} public void setEntityId(UUID v){entityId=v;} public String getPath(){return path;} public void setPath(String v){path=v;} public String getHttpMethod(){return httpMethod;} public void setHttpMethod(String v){httpMethod=v;} public String getOperationName(){return operationName;} public void setOperationName(String v){operationName=v;} public String getRequestDto(){return requestDto;} public void setRequestDto(String v){requestDto=v;} public String getResponseDto(){return responseDto;} public void setResponseDto(String v){responseDto=v;} public boolean isRequiresAuth(){return requiresAuth;} public void setRequiresAuth(boolean v){requiresAuth=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;}
}
